    async fn apply_patch_rejects_bad_diff_and_protected_paths() {
        let fx = Fixture::new();
        let tool = builtin_apply_patch(fx.tree());

        let err = tool
            .execute(serde_json::json!({ "diff": "not a diff at all" }))
